<?php /** @var \App\Models\Sale $invoice */ ?>
<section class="receipt"><header class="receipt-head"><div><span class="brand-auth">orion</span><h1><?= htmlspecialchars($invoice->business->name) ?></h1><p><?= htmlspecialchars($invoice->business->rif) ?><br><?= htmlspecialchars($invoice->business->address) ?> · <?= htmlspecialchars($invoice->business->phone) ?></p></div><div><span class="eyebrow">FACTURA</span><h2>#<?= $invoice->id ?></h2><p><?= $invoice->created_at->format('d/m/Y') ?></p><?php if($invoice->cancelled_at): ?><span class="status status-danger">ANULADA</span><?php endif ?></div></header><dl class="receipt-meta"><dt>Cliente</dt><dd><?= htmlspecialchars($invoice->client->name) ?></dd><dt>Cédula</dt><dd><?= htmlspecialchars($invoice->client->cedula) ?></dd><dt>Contacto</dt><dd><?= htmlspecialchars($invoice->client->phone) ?></dd></dl><table class="data-table"><thead><tr><th>Producto</th><th>Identificador</th><th>Subtotal</th></tr></thead><tbody><?php foreach($invoice->items as $item): ?><tr><td><?= htmlspecialchars($item->product->name) ?> × <?= $item->quantity ?></td><td><?= $item->imei1 ? htmlspecialchars($item->imei1).' / '.htmlspecialchars($item->imei2) : htmlspecialchars($item->code) ?></td><td>Bs. <?= number_format($item->getTotalVes(),2,',','.') ?></td></tr><?php endforeach ?></tbody></table><div style="text-align:right;margin-top:22px"><strong>Total: Bs. <?= number_format($invoice->getTotalVes(),2,',','.') ?></strong></div></section><script>print()</script>
